import{_ as o,a as e,b as r,c as n,d as s,e as a,f as i}from"./chunks/project-settings.D6ONafTS.js";import{_ as d,o as g,c as h,a2 as l}from"./chunks/framework.Bzj1XTnB.js";const v=JSON.parse('{"title":"The editor","description":"Find your way around the drawing screen — the bars, the toolbar, gestures, undo and zoom.","frontmatter":{"lang":"en","slug":"the-editor","order":2,"title":"The editor","description":"Find your way around the drawing screen — the bars, the toolbar, gestures, undo and zoom."},"headers":[],"relativePath":"the-editor.md","filePath":"the-editor.md"}'),p={name:"the-editor.md"};function c(u,t,m,b,f,y){return g(),h("div",null,[...t[0]||(t[0]=[l('<h1 id="the-editor" tabindex="-1">The editor <a class="header-anchor" href="#the-editor" aria-label="Permalink to &quot;The editor&quot;">​</a></h1><p>This is where you draw. Here is what every part does.</p><p><img src="'+o+'" alt="The editor"></p><h2 id="top-bar" tabindex="-1">Top bar <a class="header-anchor" href="#top-bar" aria-label="Permalink to &quot;Top bar&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Button</th><th>What it does</th></tr></thead><tbody><tr><td><strong>✕</strong></td><td>Saves and closes the project</td></tr><tr><td><strong>Pink diamond</strong></td><td>Opens the <strong>Object library</strong> to add a ready-made character or one of your saved objects</td></tr><tr><td><strong>TIMELINE</strong></td><td>Opens the full timeline (see <em>Frames and timeline</em>)</td></tr><tr><td><strong>Hide interface</strong> (the square icon)</td><td>Hides the bars so you see more of your drawing</td></tr><tr><td><strong>Pink share arrow</strong></td><td><strong>Make movie</strong> — export your animation</td></tr><tr><td><strong>⋮</strong></td><td>The project menu: add images, audio, stickers, onion skin, grid, project settings and more</td></tr></tbody></table><h2 id="the-toolbar" tabindex="-1">The toolbar <a class="header-anchor" href="#the-toolbar" aria-label="Permalink to &quot;The toolbar&quot;">​</a></h2><p>The white bar near the top holds your tools: <strong>Brush</strong>, <strong>Eraser</strong>, <strong>Lasso</strong>, <strong>Fill</strong>, one more tool that changes to the last one you used (Text at first), and <strong>⋯</strong> for the rest (<strong>Text</strong>, <strong>Smudge</strong>, <strong>Blur</strong>, <strong>Magic cut</strong>, <strong>Eyedropper</strong>).</p><p><img src="'+e+'" alt="More tools"></p><p>You can put the toolbar anywhere:</p><ul><li><strong>Drag the dotted grip</strong> on its left end to move it.</li><li><strong>Tap the grip</strong> to turn it between lying flat and standing up.</li><li><strong>Drop it at the side</strong> of the screen and it stands up along the edge.</li><li><strong>Drop it down by the frames</strong> and it folds up to just the current tool and an arrow — tap either to see every tool in a column. Drag it back up to unfold it.</li></ul><p><img src="'+r+'" alt="Folded toolbar with the tool list open"></p><h2 id="the-tool-options-pill" tabindex="-1">The tool options pill <a class="header-anchor" href="#the-tool-options-pill" aria-label="Permalink to &quot;The tool options pill&quot;">​</a></h2><p>The pill on the right edge changes with the tool. For the brush it shows <strong>Brush</strong> (choose a brush), <strong>Size</strong>, <strong>Opacity</strong>, <strong>Color</strong> and <strong>Ruler</strong>.</p><ul><li><strong>Drag up or down</strong> on a control to change it — a bubble shows the value.</li><li><strong>Tap or long-press</strong> a control to open all the settings for that tool.</li><li><strong>Tap Color</strong> to open the colour picker.</li><li>Drag its top grip to move the pill anywhere. Let go near a side and it stands against that side. (<strong>Left-handed toolbar</strong> in Settings starts it on the left edge.)</li><li>Let go of it down by the timeline and it folds to its main controls (<strong>Size</strong> and <strong>Color</strong> for the brush) and an arrow. Tap the arrow to open the rest upwards, and again to fold them. Drag it back up to unfold it.</li></ul><h2 id="the-bottom-bar" tabindex="-1">The bottom bar <a class="header-anchor" href="#the-bottom-bar" aria-label="Permalink to &quot;The bottom bar&quot;">​</a></h2><p><strong>Audio</strong>, <strong>Image/Video</strong>, <strong>Undo</strong>, <strong>Redo</strong>, <strong>Copy</strong>, <strong>Paste</strong> and <strong>Layer</strong> (the pink number is the layer you are drawing on). The frames of your animation sit just above it.</p><ul><li><strong>Copy</strong> copies what you have selected, or the whole layer if nothing is selected.</li><li><strong>Paste</strong> puts it back as a selection in <strong>the same spot</strong> — handy for carrying a drawing to the next frame.</li></ul><h2 id="gestures-on-the-canvas" tabindex="-1">Gestures on the canvas <a class="header-anchor" href="#gestures-on-the-canvas" aria-label="Permalink to &quot;Gestures on the canvas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gesture</th><th>Does</th></tr></thead><tbody><tr><td>One finger</td><td>Draws with the current tool</td></tr><tr><td>Two fingers pinch</td><td>Zoom in and out</td></tr><tr><td>Two fingers drag</td><td>Move around the canvas</td></tr><tr><td>Two fingers twist</td><td>Rotate the canvas (can be turned off in Settings)</td></tr><tr><td>Two-finger tap</td><td><strong>Undo</strong></td></tr><tr><td>Three-finger tap</td><td><strong>Redo</strong></td></tr><tr><td>Any tap while playing</td><td>Stops playback</td></tr></tbody></table><h2 id="smooth-zoom" tabindex="-1">Smooth zoom <a class="header-anchor" href="#smooth-zoom" aria-label="Permalink to &quot;Smooth zoom&quot;">​</a></h2><p>Zoom in close and your lines stay crisp instead of turning into blurry blocks of pixels. Soft brushes stay soft. Only how it looks on screen changes — your drawing and your movies are exactly the same. Needs Android 13 or newer; turn it off in <strong>Settings → Canvas &amp; gestures → Smooth zoom</strong> if you want to see the real pixels (for pixel art).</p><p><img src="'+n+'" alt="Smooth zoom off and on"></p><h2 id="hide-interface" tabindex="-1">Hide interface <a class="header-anchor" href="#hide-interface" aria-label="Permalink to &quot;Hide interface&quot;">​</a></h2><p>Tap the <strong>hide interface</strong> button to see more of your drawing. A small set of controls stays: your current tool, <strong>Show</strong> (brings everything back), <strong>Copy</strong>, <strong>Paste</strong>, play, the frame numbers and <strong>Layers</strong>.</p><p><img src="'+s+'" alt="Interface hidden"></p><h2 id="the-project-menu-⋮" tabindex="-1">The project menu (⋮) <a class="header-anchor" href="#the-project-menu-⋮" aria-label="Permalink to &quot;The project menu (⋮)&quot;">​</a></h2><p><img src="'+a+'" alt="The project menu"></p><p>At the top you see the project&#39;s size, speed and number of frames. Then:</p><ul><li><strong>Add image</strong>, <strong>Add video</strong>, <strong>Audio</strong>, <strong>Objects</strong></li><li><strong>Make sticker</strong>, <strong>Save as object</strong>, <strong>Frames</strong> (all frames in a grid), <strong>Help &amp; tips</strong></li><li><strong>Onion skin</strong> and <strong>Grid</strong> — switch them on or off here; <strong>Edit</strong> changes their settings</li><li><strong>Project settings</strong> — name, speed, timing, drawing outside the canvas and background</li><li><strong>Make movie</strong></li></ul><h2 id="project-settings" tabindex="-1">Project settings <a class="header-anchor" href="#project-settings" aria-label="Permalink to &quot;Project settings&quot;">​</a></h2><p><img src="'+i+'" alt="Project settings"></p><ul><li><strong>Project name</strong></li><li><strong>Frames per second</strong> — the speed of the whole animation (1 to 60)</li><li><strong>Timing</strong> — hold every drawing for 1, 2 or 3 frames (<strong>On ones / On twos / On threes</strong>)</li><li><strong>Canvas size</strong> — shown here, but fixed once the project exists</li><li><strong>Draw outside the canvas</strong> — room around the canvas to draw in, and <strong>Room size</strong> to set how much (see <em>Images, video and objects</em>)</li><li><strong>Background</strong> — presets, a colour or a picture</li><li><strong>Stage background</strong> — the colour around the canvas while you draw (not in your movie)</li></ul><p>Tap <strong>✓</strong> to save or <strong>✕</strong> to close without saving.</p><h2 id="leaving-the-editor" tabindex="-1">Leaving the editor <a class="header-anchor" href="#leaving-the-editor" aria-label="Permalink to &quot;Leaving the editor&quot;">​</a></h2><p><strong>✕</strong> or your phone&#39;s back button saves and closes. The back button first closes whatever is open (a menu, a sheet, a selection), so press it again to leave.</p>',35)])])}const k=d(p,[["render",c]]);export{v as __pageData,k as default};
